"""Automatic dataset insights. Every statement is computed from the data; nothing is generated by an LLM."""
import pandas as pd

from ..models.dataset import DatasetRecord
from ..schemas.api import Insight
from ..utils.formatting import fmt_num

MAX_GROUP_INSIGHTS = 4


def _strength(r: float) -> str:
    a = abs(r)
    return "weak" if a < 0.4 else "moderate" if a < 0.6 else "strong" if a < 0.8 else "very strong"


def generate_insights(record: DatasetRecord) -> list[Insight]:
    df, profile = record.df, record.profile
    insights: list[Insight] = [
        Insight(category="overview", title="Dataset size", detail=f"The dataset has {profile.rows:,} rows and {profile.columns} columns "
                f"({len(profile.numeric_columns)} numeric, {len(profile.categorical_columns)} categorical).")
    ]

    # data quality
    missing = [(c.name, c.missing) for c in profile.column_profiles if c.missing]
    if missing:
        missing.sort(key=lambda t: -t[1])
        listing = ", ".join(f"{n} ({m})" for n, m in missing[:4])
        insights.append(Insight(category="quality", title="Missing data",
                                detail=f"{profile.missing_total:,} values are missing across {len(missing)} column(s): {listing}."))
    else:
        insights.append(Insight(category="quality", title="Complete data", detail="No missing values were found."))
    if profile.duplicate_rows:
        insights.append(Insight(category="quality", title="Duplicate rows", detail=f"{profile.duplicate_rows:,} rows are exact duplicates of another row."))

    ids = {c.name for c in profile.column_profiles if c.is_identifier}
    numeric = [c for c in profile.numeric_columns if c not in ids]
    categories = [
        c.name for c in profile.column_profiles
        if c.kind == "categorical" and 2 <= c.unique <= 20 and c.unique / max(profile.rows, 1) <= 0.5
    ]

    # best / worst category per numeric column
    produced = 0
    for cat in categories[:2]:
        for num in numeric[:2]:
            if produced >= MAX_GROUP_INSIGHTS:
                break
            means = df.groupby(cat)[num].mean().dropna().sort_values(ascending=False)
            if len(means) < 2:
                continue
            insights.append(Insight(
                category="comparison", title=f"{num} by {cat}",
                detail=f"{means.index[0]} has the highest average {num} ({fmt_num(means.iloc[0])}); "
                       f"{means.index[-1]} has the lowest ({fmt_num(means.iloc[-1])}).",
            ))
            produced += 1

    # most common categories
    for cat in categories[:2]:
        vc = df[cat].dropna().astype(str).value_counts()
        if not vc.empty:
            insights.append(Insight(
                category="distribution", title=f"Most common {cat}",
                detail=f"{vc.index[0]} is the most common {cat} ({vc.iloc[0]} of {int(vc.sum())} rows, {100 * vc.iloc[0] / vc.sum():.1f}%).",
            ))

    # correlations
    if len(numeric) >= 2:
        matrix = df[numeric].corr()
        pairs = []
        for i, a in enumerate(numeric):
            for b in numeric[i + 1:]:
                r = matrix.loc[a, b]
                if pd.notna(r) and abs(r) >= 0.3:
                    pairs.append((abs(r), r, a, b))
        for _, r, a, b in sorted(pairs, reverse=True)[:3]:
            insights.append(Insight(
                category="correlation", title=f"{a} vs {b}",
                detail=f"{a} and {b} show a {_strength(r)} {'positive' if r > 0 else 'negative'} correlation (r = {r:.2f}).",
            ))

    # outliers and skew
    outlier_notes = 0
    for col in numeric:
        s = df[col].dropna()
        if len(s) < 8:
            continue
        q1, q3 = s.quantile(0.25), s.quantile(0.75)
        iqr = q3 - q1
        if iqr == 0:
            continue
        lo, hi = q1 - 1.5 * iqr, q3 + 1.5 * iqr
        n_out = int(((s < lo) | (s > hi)).sum())
        if n_out and outlier_notes < 3:
            insights.append(Insight(category="outliers", title=f"Outliers in {col}",
                                    detail=f"{n_out} value(s) in {col} fall outside the typical range ({fmt_num(lo)} to {fmt_num(hi)}) by the 1.5×IQR rule."))
            outlier_notes += 1
        skew = float(s.skew())
        if abs(skew) > 1:
            insights.append(Insight(category="distribution", title=f"{col} is skewed",
                                    detail=f"{col} is {'right' if skew > 0 else 'left'}-skewed (skewness {skew:.2f}); mean {fmt_num(s.mean())} vs median {fmt_num(s.median())}."))

    # dates
    for c in profile.column_profiles:
        if c.kind == "datetime" and c.min_value and c.max_value:
            insights.append(Insight(category="overview", title=f"{c.name} range", detail=f"{c.name} spans {c.min_value[:10]} to {c.max_value[:10]}."))
    return insights
